def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [r[:] for r in grid]
    seen = set()
    objs = []
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[i][j] == 2 for i in (r,r+1) for j in (c,c+1)) and (r,c) not in seen:
                seen.add((r,c))
                objs.append((r,c))
    # Two repeated motifs in these tasks: mark objects that have a matching
    # object at the same diagonal displacement as another, forming a 3-object line.
    # Determine the recurring displacement shared by at least three objects.
    for r,c in objs:
        for dr in range(-h,h):
            for dc in range(-w,w):
                if dr == 0 and dc == 0: continue
                if (r+dr,c+dc) in seen and (r+2*dr,c+2*dc) in seen:
                    for rr,cc in ((r,c),(r+dr,c+dc),(r+2*dr,c+2*dc)):
                        for i in (rr,rr+1):
                            for j in (cc,cc+1): out[i][j] = 8
    return out
