def transform(grid):
    """Recolor every other 2x2 square, alternating from the rightmost square."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    squares = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                squares.append((r, c))
    # Read the squares from right to left; recolor every other one, beginning
    # with the rightmost. Each object's left edge is a unique column here.
    squares.sort(key=lambda p: (-p[1], p[0]))
    for idx, (r, c) in enumerate(squares):
        if idx % 2 == 0:
            for rr in (r, r + 1):
                for cc in (c, c + 1):
                    out[rr][cc] = 8
    return out
